function adapt(input, solve, kit) {
  const values = input[1][1][0];
  const root = kit.toTree(values);
  // Remember the original nodes so that deserialize cannot hand them back.
  const original = new Set();
  const stack = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop();
    original.add(node);
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  const data = new solve().serialize(root);
  if (typeof data !== 'string') throw new Error('serialize must return a string.');
  const rebuilt = new solve().deserialize(data);
  if (rebuilt === undefined) throw new Error('deserialize did not return a value.');
  const queue = rebuilt ? [rebuilt] : [];
  for (let head = 0; head < queue.length && queue.length <= values.length + 2000; head++) {
    const node = queue[head];
    if (!node || typeof node !== 'object') throw new Error('Every child must be a TreeNode or null.');
    if (original.has(node)) throw new Error('deserialize must build new nodes from the string, not return the original tree.');
    if (node.left) queue.push(node.left);
    if (node.right) queue.push(node.right);
  }
  return kit.fromTree(rebuilt);
}

