class Codec {
  // Preorder with an explicit stack; rebuilding inserts each value into a growing BST one at a time.
  serialize(root) {
    const out = [];
    const stack = root ? [root] : [];
    while (stack.length) {
      const node = stack.pop();
      out.push(String(node.val));
      if (node.right) stack.push(node.right);
      if (node.left) stack.push(node.left);
    }
    return out.join(' ');
  }

  deserialize(data) {
    if (!data) return null;
    const values = data.split(' ').map(Number);
    const root = new TreeNode(values[0]);
    for (let i = 1; i < values.length; i++) {
      let node = root;
      for (;;) {
        if (values[i] < node.val) {
          if (!node.left) { node.left = new TreeNode(values[i]); break; }
          node = node.left;
        } else {
          if (!node.right) { node.right = new TreeNode(values[i]); break; }
          node = node.right;
        }
      }
    }
    return root;
  }
}

