function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 950 + pick(50) : pick(13);
  if (n === 0) return [["Codec", "serialize"], [[], [[]]]];
  const maxValue = large || rand() < 0.5 ? 10000 : n + pick(20);
  // A partial shuffle of 0..maxValue picks n distinct values.
  const pool = Array.from({ length: maxValue + 1 }, (_, i) => i);
  for (let i = 0; i < n; i++) { const j = i + pick(pool.length - i); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const sorted = pool.slice(0, n).sort((a, b) => a - b);
  // The insertion order decides the shape: random, ascending chain, descending chain, balanced or zigzag.
  const style = pick(5);
  let order;
  if (style === 0) {
    order = sorted.slice();
    for (let i = order.length - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
  } else if (style === 1) order = sorted.slice();
  else if (style === 2) order = sorted.slice().reverse();
  else if (style === 3) {
    order = [];
    const ranges = [[0, n - 1]];
    for (let head = 0; head < ranges.length; head++) {
      const [lo, hi] = ranges[head];
      if (lo > hi) continue;
      const mid = (lo + hi) >> 1;
      order.push(sorted[mid]);
      ranges.push([lo, mid - 1], [mid + 1, hi]);
    }
  } else {
    order = [];
    let lo = 0, hi = n - 1;
    while (lo <= hi) order.push(order.length % 2 ? sorted[hi--] : sorted[lo++]);
  }
  const nodes = [{ val: order[0], left: null, right: null }];
  for (let i = 1; i < order.length; i++) {
    let node = nodes[0];
    const fresh = { val: order[i], left: null, right: null };
    for (;;) {
      const side = order[i] < node.val ? 'left' : 'right';
      if (!node[side]) { node[side] = fresh; break; }
      node = node[side];
    }
  }
  const root = [];
  const queue = [nodes[0]];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    if (!node) { root.push(null); continue; }
    root.push(node.val);
    queue.push(node.left, node.right);
  }
  while (root[root.length - 1] === null) root.pop();
  return [["Codec", "serialize"], [[], [root]]];
}
